// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — URL Handler (Module 10 v2 — Step 10.7). * * Opens URLs in the appropriate app (browser for http/https, dialer for tel, * maps for geo, etc.). * * ## Security (per strategy §"Apps") * *  - **Allowed schemes**: http, https, mailto, tel, sms, geo, market, intent. *  - **Blocked schemes**: `file://`, `content://` — could leak local files *    or content provider data to malicious handlers. * * A blocked scheme returns `Result.Failure(Hardware.Unsupported)` with the * message "URL scheme 'file' not allowed for security". * * ## Reversibility * * Not reversible — can't "un-open" a URL. Implements plain * [SystemOperationHandler]. * * ## Resource category * * URL opens use [ResourceCategory.SETTINGS] — multiple URL opens in a batch * run in parallel. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Scope — URLs</a> */class UrlHandler(    private val urlLauncherService: UrlLauncherService,) : StatelessSystemOperationHandler<SystemOperation.OpenUrl>() {    override val id: String = "url"    override val displayName: String = "URL Opener"    override val requiredPermissions: Set<String> = emptySet()    override val resourceCategory: ResourceCategory = ResourceCategory.SETTINGS    override fun isAvailable(): Boolean = true  // all devices can open URLs    override suspend fun execute(operation: SystemOperation.OpenUrl): Result<Unit> {        // Security: reject disallowed schemes (file://, content://).        if (!urlLauncherService.isSchemeAllowed(operation.url)) {            val scheme = try {                android.net.Uri.parse(operation.url).scheme            } catch (t: Throwable) { null }            Timber.tag("UrlHandler").w("URL scheme blocked: $scheme (url=${operation.url})")            return Result.Failure(                error = AppError.Hardware.Unsupported(                    resource = "url_scheme:${scheme ?: "null"}",                    cause = null,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        val opened = urlLauncherService.openUrl(operation.url)        return if (opened) {            Result.Success(Unit, CorrelationId.generate(), 0)        } else {            Result.Failure(                error = AppError.Hardware.Unsupported(                    resource = "url_handler",                    cause = null,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }}
